<section class="dash-card jobs-card" id="jobs"><div class="card-title"><h2>پروژه‌های من</h2><span><?=count($jobs)?> پروژه</span></div><?php foreach($jobs as $job):?><article class="job-item"><div class="job-info"><h3><?=e($job['title'])?></h3><p><?=e(mb_strimwidth($job['description'],0,150,'…'))?></p><small><?=e($job['proposal_count'])?> پیشنهاد · <?=e($job['budget_min'])?> تا <?=e($job['budget_max'])?> دلار</small></div><div class="job-actions"><form method="post" action="<?=url('/dashboard/employer/jobs/status')?>"><?=csrf_field()?><input type="hidden" name="job_id" value="<?=e($job['id'])?>"><select name="status"><option value="open">انتشار</option><option value="paused">توقف موقت</option><option value="completed">تکمیل</option><option value="cancelled">لغو</option></select><button class="button button-small">تغییر وضعیت</button></form><form method="post" action="<?=url('/dashboard/employer/jobs/delete')?>" onsubmit="return confirm('حذف پروژه؟')"><?=csrf_field()?><input type="hidden" name="job_id" value="<?=e($job['id'])?>"><button class="action-button suspend">حذف</button></form></div></article><?php endforeach;?><?php if(!$jobs):?><p class="empty-state">هنوز پروژه‌ای منتشر نکرده‌اید.</p><?php endif;?></section>